1223: void plist_dict_next_item(plist_t node, plist_dict_iter iter, char **key, plist_t *val)
1224: {
1225:     if (key) *key = NULL;
1226:     if (val) *val = NULL;
1227:     if (!iter) return;
1228:     if (!PLIST_IS_DICT(node)) return;
1229: 
1230:     plist_dict_iter_private* it = (plist_dict_iter_private*)iter;
1231: 
1232:     node_t k = it->cur;
1233:     if (!k) return;
1234: 
1235:     if (!PLIST_IS_KEY((plist_t)k)) {
1236:         // malformed dict, terminate iteration
1237:         it->cur = NULL;
1238:         return;
1239:     }
1240: 
1241:     node_t v = node_next_sibling(k);
1242:     if (!v) {
1243:         // key without value, terminate iteration
1244:         it->cur = NULL;
1245:         return;
1246:     }
1247: 
1248:     if (key) {
1249:         plist_get_key_val((plist_t)k, key);
1250:     }
1251:     if (val) {
1252:         *val = (plist_t)v;
1253:     }
1254:     it->cur = node_next_sibling(v);
1255: }
