        // detach old value (do NOT free yet)
        int idx = node_detach((node_t)node, old_val);
        if (idx < 0) {
            PLIST_ERR("%s: failed to detach old value (err=%d)\n", __func__, idx);
            return PLIST_ERR_UNKNOWN;
