163: static int is_exception_century(Year year)
164: {
165:     int is_exception = ((year % 100 == 0) && !(year % 400 == 0));
166:     TIME64_TRACE1("# is_exception_century: %s\n", is_exception ? "yes" : "no");
167: 
168:     return(is_exception);
