172: /* Compare two dates.
173:    The result is like cmp.
174:    Ignores things like gmtoffset and dst
175: */
176: static int cmp_date( const struct TM* left, const struct tm* right ) {
177:     if( left->tm_year > right->tm_year )
178:         return 1;
179:     if( left->tm_year < right->tm_year )
180:         return -1;
181:     if( left->tm_mon > right->tm_mon )
182:         return 1;
183:     if( left->tm_mon < right->tm_mon )
184:         return -1;
185:     if( left->tm_mday > right->tm_mday )
186:         return 1;
187:     if( left->tm_mday < right->tm_mday )
188:         return -1;
189:     if( left->tm_hour > right->tm_hour )
190:         return 1;
191:     if( left->tm_hour < right->tm_hour )
192:         return -1;
193:     if( left->tm_min > right->tm_min )
194:         return 1;
195:     if( left->tm_min < right->tm_min )
196:         return -1;
197:     if( left->tm_sec > right->tm_sec )
198:         return 1;
199:     if( left->tm_sec < right->tm_sec )
200:         return -1;
201:     return 0;
202: }
