205: /* Check if a date is safely inside a range.
206:    The intention is to check if its a few days inside.
207: */
208: static int date_in_safe_range( const struct TM* date, const struct tm* min, const struct tm* max ) {
209:     if( cmp_date(date, min) == -1 )
210:         return 0;
211: 
212:     if( cmp_date(date, max) == 1 )
213:         return 0;
214: 
215:     return 1;
216: }
