219: /* timegm() is not in the C or POSIX spec, but it is such a useful
220:    extension I would be remiss in leaving it out.  Also I need it
221:    for localtime64()
222: */
223: Time64_T timegm64(const struct TM *date) {
224:     Time64_T days    = 0;
225:     Time64_T seconds = 0;
226:     Year     year;
227:     assert(date != NULL);
228:     Year     orig_year = (Year)date->tm_year;
229:     int      cycles  = 0;
230: 
231:     if( (orig_year > 100) || (orig_year < -300) ) {
232:         cycles = (orig_year - 100) / 400;
233:         orig_year -= cycles * 400;
234:         days      += (Time64_T)cycles * days_in_gregorian_cycle;
235:     }
236:     TIME64_TRACE3("# timegm/ cycles: %d, days: %lld, orig_year: %lld\n", cycles, days, orig_year);
237: 
238:     if( orig_year > 70 ) {
239:         year = 70;
240:         while( year < orig_year ) {
241:             days += length_of_year[IS_LEAP(year)];
242:             year++;
243:         }
244:     }
245:     else if ( orig_year < 70 ) {
246:         year = 69;
247:         do {
248:             days -= length_of_year[IS_LEAP(year)];
249:             year--;
250:         } while( year >= orig_year );
251:     }
252: 
253:     days += julian_days_by_month[IS_LEAP(orig_year)][date->tm_mon];
254:     days += date->tm_mday - 1;
255: 
256:     seconds = days * 60 * 60 * 24;
257: 
258:     seconds += date->tm_hour * 60 * 60;
259:     seconds += date->tm_min * 60;
260:     seconds += date->tm_sec;
261: 
262:     return(seconds);
263: }
