266: static int check_tm(struct TM *tm)
267: {
268:     /* Don't forget leap seconds */
269:     assert(tm->tm_sec >= 0);
270:     assert(tm->tm_sec <= 61);
271: 
272:     assert(tm->tm_min >= 0);
273:     assert(tm->tm_min <= 59);
274: 
275:     assert(tm->tm_hour >= 0);
276:     assert(tm->tm_hour <= 23);
277: 
278:     assert(tm->tm_mday >= 1);
279:     assert(tm->tm_mday <= days_in_month[IS_LEAP(tm->tm_year)][tm->tm_mon]);
280: 
281:     assert(tm->tm_mon  >= 0);
282:     assert(tm->tm_mon  <= 11);
283: 
284:     assert(tm->tm_wday >= 0);
285:     assert(tm->tm_wday <= 6);
286: 
287:     assert(tm->tm_yday >= 0);
288:     assert(tm->tm_yday <= length_of_year[IS_LEAP(tm->tm_year)]);
289: 
290: #ifdef HAVE_TM_TM_GMTOFF
291:     assert(tm->tm_gmtoff >= -24 * 60 * 60);
292:     assert(tm->tm_gmtoff <=  24 * 60 * 60);
293: #endif
294: 
295:     return 1;
296: }
