299: /* The exceptional centuries without leap years cause the cycle to
300:    shift by 16
301: */
302: static Year cycle_offset(Year year)
303: {
304:     const Year start_year = 2000;
305:     Year year_diff  = year - start_year;
306:     Year exceptions;
307: 
308:     if( year > start_year )
309:         year_diff--;
310: 
311:     exceptions  = year_diff / 100;
312:     exceptions -= year_diff / 400;
313: 
314:     TIME64_TRACE3("# year: %lld, exceptions: %lld, year_diff: %lld\n",
315:           year, exceptions, year_diff);
316: 
317:     return exceptions * 16;
318: }
319: 
320: /* For a given year after 2038, pick the latest possible matching
321:    year in the 28 year calendar cycle.
322: 
323:    A matching year...
324:    1) Starts on the same day of the week.
325:    2) Has the same leap year status.
326: 
327:    This is so the calendars match up.
328: 
329:    Also the previous year must match.  When doing Jan 1st you might
330:    wind up on Dec 31st the previous year when doing a -UTC time zone.
331: 
332:    Finally, the next year must have the same start day of week.  This
333:    is for Dec 31st with a +UTC time zone.
334:    It doesn't need the same leap year status since we only care about
335:    January 1st.
336: */
337: static int safe_year(const Year year)
338: {
339:     int _safe_year = (int)year;
340:     Year year_cycle;
341: 
342:     if( year >= MIN_SAFE_YEAR && year <= MAX_SAFE_YEAR ) {
343:         return _safe_year;
344:     }
345: 
346:     year_cycle = year + cycle_offset(year);
347: 
348:     /* safe_years_low is off from safe_years_high by 8 years */
349:     if( year < MIN_SAFE_YEAR )
350:         year_cycle -= 8;
351: 
352:     /* Change non-leap xx00 years to an equivalent */
353:     if( is_exception_century(year) )
354:         year_cycle += 11;
355: 
356:     /* Also xx01 years, since the previous year will be wrong */
357:     if( is_exception_century(year - 1) )
358:         year_cycle += 17;
359: 
360:     year_cycle %= SOLAR_CYCLE_LENGTH;
361:     if( year_cycle < 0 )
362:         year_cycle = SOLAR_CYCLE_LENGTH + year_cycle;
363: 
364:     assert( year_cycle >= 0 );
365:     assert( year_cycle < SOLAR_CYCLE_LENGTH );
366:     if( year < MIN_SAFE_YEAR )
367:         _safe_year = safe_years_low[year_cycle];
368:     else if( year > MAX_SAFE_YEAR )
369:         _safe_year = safe_years_high[year_cycle];
370:     else
371:         assert(0);
372: 
373:     TIME64_TRACE3("# year: %lld, year_cycle: %lld, safe_year: %d\n",
374:           year, year_cycle, _safe_year);
375: 
376:     assert(_safe_year <= MAX_SAFE_YEAR && _safe_year >= MIN_SAFE_YEAR);
377: 
378:     return _safe_year;
379: }
