484: static Time64_T seconds_between_years(Year left_year, Year right_year) {
485:     int increment = (left_year > right_year) ? 1 : -1;
486:     Time64_T seconds = 0;
487:     int cycles;
488: 
489:     if( left_year > 2400 ) {
490:         cycles = (left_year - 2400) / 400;
491:         left_year -= cycles * 400;
492:         seconds   += cycles * seconds_in_gregorian_cycle;
493:     }
494:     else if( left_year < 1600 ) {
495:         cycles = (left_year - 1600) / 400;
496:         left_year += cycles * 400;
497:         seconds   += cycles * seconds_in_gregorian_cycle;
498:     }
499: 
500:     while( left_year != right_year ) {
501:         seconds += length_of_year[IS_LEAP(right_year - 1900)] * 60 * 60 * 24;
502:         right_year += increment;
503:     }
504: 
505:     return seconds * increment;
506: }
