509: Time64_T mktime64(struct TM *input_date) {
510:     struct tm safe_date;
511:     struct TM date;
512:     Time64_T  timev;
513:     Year      year = input_date->tm_year + 1900;
514: 
515:     if( date_in_safe_range(input_date, &SYSTEM_MKTIME_MIN, &SYSTEM_MKTIME_MAX) )
516:     {
517:         copy_TM64_to_tm(input_date, &safe_date);
518:         timev = (Time64_T)mktime(&safe_date);
519: 
520:         /* Correct the possibly out of bound input date */
521:         copy_tm_to_TM64(&safe_date, input_date);
522:         return timev;
523:     }
524: 
525:     /* Have to make the year safe in date else it won't fit in safe_date */
526:     date = *input_date;
527:     date.tm_year = safe_year(year) - 1900;
528:     copy_TM64_to_tm(&date, &safe_date);
529: 
530:     timev = (Time64_T)mktime(&safe_date);
531: 
532:     /* Correct the user's possibly out of bound input date */
533:     copy_tm_to_TM64(&safe_date, input_date);
534: 
535:     timev += seconds_between_years(year, (Year)(safe_date.tm_year) + 1900);
536: 
537:     return timev;
538: }
