547: struct TM *gmtime64_r (const Time64_T *in_time, struct TM *p)
548: {
549:     int v_tm_sec, v_tm_min, v_tm_hour, v_tm_mon, v_tm_wday;
550:     Time64_T v_tm_tday;
551:     int leap;
552:     Time64_T m;
553:     Time64_T timev = *in_time;
554:     Year year = 70;
555:     int cycles = 0;
556: 
557:     assert(p != NULL);
558: 
559:     /* Use the system gmtime() if time_t is small enough */
560:     if( SHOULD_USE_SYSTEM_GMTIME(*in_time) ) {
561:         time_t safe_time = (time_t)*in_time;
562:         struct tm safe_date;
563:         GMTIME_R(&safe_time, &safe_date);
564: 
565:         copy_tm_to_TM64(&safe_date, p);
566:         assert(check_tm(p));
567: 
568:         return p;
569:     }
570: 
571: #ifdef HAVE_TM_TM_GMTOFF
572:     p->tm_gmtoff = 0;
573: #endif
574:     p->tm_isdst  = 0;
575: 
576: #ifdef HAVE_TM_TM_ZONE
577:     p->tm_zone   = (char*)"UTC";
578: #endif
579: 
580:     v_tm_sec =  (int)(timev % 60);
581:     timev /= 60;
582:     v_tm_min =  (int)(timev % 60);
583:     timev /= 60;
584:     v_tm_hour = (int)(timev % 24);
585:     timev /= 24;
586:     v_tm_tday = timev;
587: 
588:     WRAP (v_tm_sec, v_tm_min, 60);
589:     WRAP (v_tm_min, v_tm_hour, 60);
590:     WRAP (v_tm_hour, v_tm_tday, 24);
591: 
592:     v_tm_wday = (int)((v_tm_tday + 4) % 7);
593:     if (v_tm_wday < 0)
594:         v_tm_wday += 7;
595:     m = v_tm_tday;
596: 
597:     if (m >= CHEAT_DAYS) {
598:         year = CHEAT_YEARS;
599:         m -= CHEAT_DAYS;
600:     }
601: 
602:     if (m >= 0) {
603:         /* Gregorian cycles, this is huge optimization for distant times */
604:         cycles = (int)(m / (Time64_T) days_in_gregorian_cycle);
605:         if( cycles ) {
606:             m -= (cycles * (Time64_T) days_in_gregorian_cycle);
607:             year += (cycles * years_in_gregorian_cycle);
608:         }
609: 
610:         /* Years */
611:         leap = IS_LEAP (year);
612:         while (m >= (Time64_T) length_of_year[leap]) {
613:             m -= (Time64_T) length_of_year[leap];
614:             year++;
615:             leap = IS_LEAP (year);
616:         }
617: 
618:         /* Months */
619:         v_tm_mon = 0;
620:         while (m >= (Time64_T) days_in_month[leap][v_tm_mon]) {
621:             m -= (Time64_T) days_in_month[leap][v_tm_mon];
622:             v_tm_mon++;
623:         }
624:     } else {
625:         year--;
626: 
627:         /* Gregorian cycles */
628:         cycles = (int)((m / (Time64_T) days_in_gregorian_cycle) + 1);
629:         if( cycles ) {
630:             m -= (cycles * (Time64_T) days_in_gregorian_cycle);
631:             year += (cycles * years_in_gregorian_cycle);
632:         }
633: 
634:         /* Years */
635:         leap = IS_LEAP (year);
636:         while (m < (Time64_T) -length_of_year[leap]) {
637:             m += (Time64_T) length_of_year[leap];
638:             year--;
639:             leap = IS_LEAP (year);
640:         }
641: 
642:         /* Months */
643:         v_tm_mon = 11;
644:         while (m < (Time64_T) -days_in_month[leap][v_tm_mon]) {
645:             m += (Time64_T) days_in_month[leap][v_tm_mon];
646:             v_tm_mon--;
647:         }
648:         m += (Time64_T) days_in_month[leap][v_tm_mon];
649:     }
650: 
651:     p->tm_year = year;
652:     if( p->tm_year != year ) {
653: #ifdef EOVERFLOW
654:         errno = EOVERFLOW;
655: #endif
656:         return NULL;
657:     }
658: 
659:     /* At this point m is less than a year so casting to an int is safe */
660:     p->tm_mday = (int) m + 1;
661:     p->tm_yday = julian_days_by_month[leap][v_tm_mon] + (int)m;
662:     p->tm_sec  = v_tm_sec;
663:     p->tm_min  = v_tm_min;
664:     p->tm_hour = v_tm_hour;
665:     p->tm_mon  = v_tm_mon;
666:     p->tm_wday = v_tm_wday;
667: 
668:     assert(check_tm(p));
669: 
670:     return p;
671: }
