674: struct TM *localtime64_r (const Time64_T *timev, struct TM *local_tm)
675: {
676:     time_t safe_time;
677:     struct tm safe_date;
678:     struct TM gm_tm;
679:     Year orig_year;
680:     int month_diff;
681: 
682:     assert(local_tm != NULL);
683: 
684:     /* Use the system localtime() if time_t is small enough */
685:     if( SHOULD_USE_SYSTEM_LOCALTIME(*timev) ) {
686:         safe_time = (time_t)*timev;
687: 
688:         TIME64_TRACE1("Using system localtime for %lld\n", *timev);
689: 
690:         LOCALTIME_R(&safe_time, &safe_date);
691: 
692:         copy_tm_to_TM64(&safe_date, local_tm);
693:         assert(check_tm(local_tm));
694: 
695:         return local_tm;
696:     }
697: 
698:     if( gmtime64_r(timev, &gm_tm) == NULL ) {
699:         TIME64_TRACE1("gmtime64_r returned null for %lld\n", *timev);
700:         return NULL;
701:     }
702: 
703:     orig_year = gm_tm.tm_year;
704: 
705:     if (gm_tm.tm_year > (2037 - 1900) ||
706:         gm_tm.tm_year < (1970 - 1900)
707:        )
708:     {
709:         TIME64_TRACE1("Mapping tm_year %lld to safe_year\n", (Year)gm_tm.tm_year);
710:         gm_tm.tm_year = safe_year((Year)(gm_tm.tm_year) + 1900) - 1900;
711:     }
712: 
713:     safe_time = (time_t)timegm64(&gm_tm);
714:     if( LOCALTIME_R(&safe_time, &safe_date) == NULL ) {
715:         TIME64_TRACE1("localtime_r(%d) returned NULL\n", (int)safe_time);
716:         return NULL;
717:     }
718: 
719:     copy_tm_to_TM64(&safe_date, local_tm);
720: 
721:     local_tm->tm_year = orig_year;
722:     if( local_tm->tm_year != orig_year ) {
723:         TIME64_TRACE2("tm_year overflow: tm_year %lld, orig_year %lld\n",
724:               (Year)local_tm->tm_year, (Year)orig_year);
725: 
726: #ifdef EOVERFLOW
727:         errno = EOVERFLOW;
728: #endif
729:         return NULL;
730:     }
731: 
732: 
733:     month_diff = local_tm->tm_mon - gm_tm.tm_mon;
734: 
735:     /*  When localtime is Dec 31st previous year and
736:         gmtime is Jan 1st next year.
737:     */
738:     if( month_diff == 11 ) {
739:         local_tm->tm_year--;
740:     }
741: 
742:     /*  When localtime is Jan 1st, next year and
743:         gmtime is Dec 31st, previous year.
744:     */
745:     if( month_diff == -11 ) {
746:         local_tm->tm_year++;
747:     }
748: 
749:     /* GMT is Jan 1st, xx01 year, but localtime is still Dec 31st
750:        in a non-leap xx00.  There is one point in the cycle
751:        we can't account for which the safe xx00 year is a leap
752:        year.  So we need to correct for Dec 31st comming out as
753:        the 366th day of the year.
754:     */
755:     if( !IS_LEAP(local_tm->tm_year) && local_tm->tm_yday == 365 )
756:         local_tm->tm_yday--;
757: 
