                        fprintf(stderr, "ERROR: Failed to reallocate stdin buffer\n");
                        free(plist_entire);
                        free(options);
                        return 1;
                    }
                    plist_entire = tmp;
                    read_capacity = newcap;
                }

                memcpy(plist_entire + read_size, buf, (size_t)n);
                read_size += (size_t)n;
                continue;
