                    if (*tok == '\0') continue;
                    switch (plist_get_node_type(current)) {
                        case PLIST_DICT:
                            current = plist_dict_get_item(current, tok);
                            break;
                        case PLIST_ARRAY: {
                            char* endp = NULL;
                            uint32_t idx = strtoul(tok, &endp, 10);
                            if (endp == tok || *endp != '\0') {
                                current = NULL;
